package com.example.cache

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.server.request.*
import io.ktor.client.*
import io.ktor.client.request.*
import io.ktor.client.statement.*
import io.ktor.http.*
import java.util.concurrent.ConcurrentHashMap
import java.time.Instant
import java.time.Duration

data class CacheEntry(
    val content: String,
    val headers: Map<String, String>,
    val cachedAt: Instant,
    val ttl: Duration
)

val responseCache = ConcurrentHashMap<String, CacheEntry>()
val httpClient = HttpClient()

fun computeCacheKey(request: ApplicationRequest): String {
    // Cache key derived from path + Host header + X-Forwarded-Host
    val path = request.path()
    val host = request.headers["Host"] ?: "default"
    val forwardedHost = request.headers["X-Forwarded-Host"] ?: ""
    return "$host|$forwardedHost|$path"
}

fun isExpired(entry: CacheEntry): Boolean {
    return Instant.now().isAfter(entry.cachedAt.plus(entry.ttl))
}

suspend fun fetchFromUpstream(path: String, forwardedHost: String): Pair<String, Map<String, String>> {
    val targetHost = if (forwardedHost.isNotEmpty()) forwardedHost else "backend-service.internal"
    val response = httpClient.get("http://$targetHost$path")
    val body = response.bodyAsText()
    val respHeaders = mapOf(
        "Content-Type" to (response.headers["Content-Type"] ?: "text/html"),
        "X-Cache-Status" to "MISS"
    )
    return Pair(body, respHeaders)
}

fun main() {
    embeddedServer(Netty, port = 8080) {
        routing {
            get("/health") {
                call.respondText("OK", ContentType.Text.Plain)
            }

            // Proxy endpoint with caching layer
            get("{path...}") {
                val cacheKey = computeCacheKey(call.request)
                val cached = responseCache[cacheKey]

                if (cached != null && !isExpired(cached)) {
                    cached.headers.forEach { (k, v) -> call.response.header(k, v) }
                    call.response.header("X-Cache-Status", "HIT")
                    call.respondText(cached.content, ContentType.Text.Html)
                    return@get
                }

                val path = call.request.path()
                val forwardedHost = call.request.headers["X-Forwarded-Host"] ?: ""

                try {
                    val (body, headers) = fetchFromUpstream(path, forwardedHost)

                    // Store in cache - TTL from upstream Cache-Control or default 300s
                    val entry = CacheEntry(
                        content = body,
                        headers = headers,
                        cachedAt = Instant.now(),
                        ttl = Duration.ofSeconds(300)
                    )
                    responseCache[cacheKey] = entry

                    headers.forEach { (k, v) -> call.response.header(k, v) }
                    call.respondText(body, ContentType.Text.Html)
                } catch (e: Exception) {
                    call.respondText(
                        "Upstream unavailable",
                        ContentType.Text.Plain,
                        HttpStatusCode.BadGateway
                    )
                }
            }

            // Cache purge endpoint - no auth check
            post("/admin/cache/purge") {
                val key = call.receiveText()
                if (key == "*") {
                    responseCache.clear()
                } else {
                    responseCache.remove(key)
                }
                call.respondText("Purged", ContentType.Text.Plain)
            }
        }
    }.start(wait = true)
}
